import React, { useState, useEffect, useRef } from 'react';
import './CalculatorWidget.css';

const CalculatorWidget = ({ onClose, isVisible = true }) => {
  const [input, setInput] = useState('');
  const [result, setResult] = useState('0');
  const [angleMode, setAngleMode] = useState('deg'); // 'deg' or 'rad'
  const [activeTab, setActiveTab] = useState('main'); // 'main' or 'func'
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const dragOffset = useRef({ x: 0, y: 0 });
  const widgetRef = useRef(null);

  // Initialize position (center screen roughly)
  useEffect(() => {
    const initialX = window.innerWidth / 2 - 175; // Half of width (350px)
    const initialY = window.innerHeight * 0.15; // 15vh
    setPosition({ x: initialX, y: initialY });
  }, []);

  // --- Dragging Logic ---
  const handleMouseDown = (e) => {
    if (e.target.closest('.calculator-close-btn') || e.target.closest('.calculator-tabs') || e.target.closest('.button-section')) return;

    setIsDragging(true);
    dragOffset.current = {
      x: e.clientX - position.x,
      y: e.clientY - position.y
    };
  };

  const handleMouseMove = (e) => {
    if (isDragging) {
      setPosition({
        x: e.clientX - dragOffset.current.x,
        y: e.clientY - dragOffset.current.y
      });
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  useEffect(() => {
    if (isDragging) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
    } else {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    }
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging]);

  // --- Calculator Logic ---
  const appendToInput = (value) => {
    setInput((prev) => prev + value);
  };

  const clearAll = () => {
    setInput('');
    setResult('0');
  };

  const backspace = () => {
    setInput((prev) => prev.slice(0, -1));
  };

  const calculate = () => {
    if (!input.trim()) return;

    try {
      let expression = input
        .replace(/×/g, '*')
        .replace(/÷/g, '/')
        .replace(/\^/g, '**') // Power operator
        .replace(/π/g, 'Math.PI')
        .replace(/e/g, 'Math.E')
        .replace(/sqrt\(/g, 'Math.sqrt(')
        .replace(/log\(/g, 'Math.log10(')
        .replace(/ln\(/g, 'Math.log(');

      // Handle angle mode for trig functions
      if (angleMode === 'deg') {
        expression = expression
          .replace(/sin\(/g, 'Math.sin(Math.PI/180*')
          .replace(/cos\(/g, 'Math.cos(Math.PI/180*')
          .replace(/tan\(/g, 'Math.tan(Math.PI/180*');
      } else {
        expression = expression
          .replace(/sin\(/g, 'Math.sin(')
          .replace(/cos\(/g, 'Math.cos(')
          .replace(/tan\(/g, 'Math.tan(');
      }

      // Safe evaluation is hard in frontend without 'eval', but valid for a widget like this
      // eslint-disable-next-line no-eval
      const evalResult = eval(expression);

      if (isNaN(evalResult) || !isFinite(evalResult)) {
        throw new Error('Invalid calculation');
      }

      // Format result (max 12 precision)
      const formattedResult = Number(evalResult.toPrecision(12)).toString();
      setResult(formattedResult);

      // Optional: Auto-update input to result for chaining
      // setInput(formattedResult); 
    } catch (error) {
      setResult('Error');
      setTimeout(() => setResult('0'), 2000);
    }
  };

  // Keyboard support
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (!isVisible) return;

      if (e.key >= '0' && e.key <= '9') appendToInput(e.key);
      if (e.key === '.') appendToInput('.');
      if (e.key === '+') appendToInput('+');
      if (e.key === '-') appendToInput('-');
      if (e.key === '*') appendToInput('*');
      if (e.key === '/') appendToInput('/');
      if (e.key === 'Enter') calculate();
      if (e.key === 'Backspace') backspace();
      if (e.key === 'Escape') {
        if (input) clearAll();
        else if (onClose) onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [input, isVisible, onClose]);


  if (!isVisible) return null;

  return (
    <div
      ref={widgetRef}
      className="calculator-widget"
      style={{
        left: `${position.x}px`,
        top: `${position.y}px`,
        transform: 'none' // Override CSS transform to allow drag
      }}
    >
      <div className="calculator-label" onMouseDown={handleMouseDown}>
        NOVA CALCULATOR
        {onClose && (
          <button className="calculator-close-btn" onClick={onClose} title="Close Calculator">
            ✕
          </button>
        )}
      </div>

      <div className="calculator-screen-area">
        <div className="calculator-input">{input || '0'}</div>
        <div className="calculator-result">{result}</div>
      </div>

      <div className="controls-section">
        <div className="calculator-tabs">
          <button
            className={`tab-button ${activeTab === 'main' ? 'active' : ''}`}
            onClick={() => setActiveTab('main')}
          >
            Main
          </button>
          <button
            className={`tab-button ${activeTab === 'func' ? 'active' : ''}`}
            onClick={() => setActiveTab('func')}
          >
            Scientific
          </button>
        </div>

        {activeTab === 'func' && (
          <div className="angle-mode">
            <button
              className={`angle-button ${angleMode === 'deg' ? 'active' : ''}`}
              onClick={() => setAngleMode('deg')}
            >
              DEG
            </button>
            <button
              className={`angle-button ${angleMode === 'rad' ? 'active' : ''}`}
              onClick={() => setAngleMode('rad')}
            >
              RAD
            </button>
          </div>
        )}
      </div>

      <div className="button-section">
        {activeTab === 'main' ? (
          <div className="calculator-buttons">
            <button className="calc-btn clear" onClick={clearAll}>C</button>
            <button className="calc-btn backspace" onClick={backspace}>⌫</button>
            <button className="calc-btn operator" onClick={() => appendToInput('(')}>(</button>
            <button className="calc-btn operator" onClick={() => appendToInput(')')}>)</button>

            <button className="calc-btn" onClick={() => appendToInput('7')}>7</button>
            <button className="calc-btn" onClick={() => appendToInput('8')}>8</button>
            <button className="calc-btn" onClick={() => appendToInput('9')}>9</button>
            <button className="calc-btn operator" onClick={() => appendToInput('/')}>÷</button>

            <button className="calc-btn" onClick={() => appendToInput('4')}>4</button>
            <button className="calc-btn" onClick={() => appendToInput('5')}>5</button>
            <button className="calc-btn" onClick={() => appendToInput('6')}>6</button>
            <button className="calc-btn operator" onClick={() => appendToInput('*')}>×</button>

            <button className="calc-btn" onClick={() => appendToInput('1')}>1</button>
            <button className="calc-btn" onClick={() => appendToInput('2')}>2</button>
            <button className="calc-btn" onClick={() => appendToInput('3')}>3</button>
            <button className="calc-btn operator" onClick={() => appendToInput('-')}>-</button>

            <button className="calc-btn zero" onClick={() => appendToInput('0')}>0</button>
            <button className="calc-btn" onClick={() => appendToInput('.')}>.</button>
            <button className="calc-btn operator" onClick={() => appendToInput('+')}>+</button>

            <button
              className="calc-btn equals"
              style={{ gridColumn: 'span 4', marginTop: '8px' }}
              onClick={calculate}
            >
              =
            </button>
          </div>
        ) : (
          <div className="calculator-buttons" style={{ gridTemplateColumns: 'repeat(4, 1fr)' }}>
            {/* Scientific Row 1 */}
            <button className="calc-btn scientific" onClick={() => appendToInput('sin(')}>sin</button>
            <button className="calc-btn scientific" onClick={() => appendToInput('cos(')}>cos</button>
            <button className="calc-btn scientific" onClick={() => appendToInput('tan(')}>tan</button>
            <button className="calc-btn operator" onClick={() => appendToInput('^')}>^</button>

            {/* Scientific Row 2 */}
            <button className="calc-btn scientific" onClick={() => appendToInput('sqrt(')}>√</button>
            <button className="calc-btn scientific" onClick={() => appendToInput('log(')}>log</button>
            <button className="calc-btn scientific" onClick={() => appendToInput('ln(')}>ln</button>
            <button className="calc-btn scientific" onClick={() => appendToInput('PI')}>π</button>

            {/* Scientific Row 3 */}
            <button className="calc-btn scientific" onClick={() => appendToInput('e')}>e</button>
            <button className="calc-btn" onClick={() => appendToInput('(')}>(</button>
            <button className="calc-btn" onClick={() => appendToInput(')')}>)</button>
            <button className="calc-btn backspace" onClick={backspace}>⌫</button>

            {/* Numpad mini (bottom rows) */}
            <button className="calc-btn" onClick={() => appendToInput('7')}>7</button>
            <button className="calc-btn" onClick={() => appendToInput('8')}>8</button>
            <button className="calc-btn" onClick={() => appendToInput('9')}>9</button>
            <button className="calc-btn operator" onClick={() => appendToInput('/')}>÷</button>

            <button className="calc-btn" onClick={() => appendToInput('4')}>4</button>
            <button className="calc-btn" onClick={() => appendToInput('5')}>5</button>
            <button className="calc-btn" onClick={() => appendToInput('6')}>6</button>
            <button className="calc-btn operator" onClick={() => appendToInput('*')}>×</button>

            <button className="calc-btn" onClick={() => appendToInput('1')}>1</button>
            <button className="calc-btn" onClick={() => appendToInput('2')}>2</button>
            <button className="calc-btn" onClick={() => appendToInput('3')}>3</button>
            <button className="calc-btn operator" onClick={() => appendToInput('-')}>-</button>

            <button className="calc-btn zero" onClick={() => appendToInput('0')}>0</button>
            <button className="calc-btn" onClick={() => appendToInput('.')}>.</button>
            <button className="calc-btn operator" onClick={() => appendToInput('+')}>+</button>

            {/* Large Equals */}
            <button
              className="calc-btn equals"
              style={{ gridColumn: 'span 4', marginTop: '8px' }}
              onClick={calculate}
            >
              =
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default CalculatorWidget;
